    affLastValdte: "Wednesday - Dec 22, 2021 06:42",
    affDueValdte: "12/22/2022",
    affActivities: "In 2021, we supported several key events and worked in general on resurrecting the Albany TVC. We brought back the Albany Nanotechnology Symposium, which was cancelled last year; the lunch and learn TVC seminars, which had stopped last year, and the EDS fall school in lieu of FinTech conference, which was also cancelled last year. We also had a virtual speed mentoring session, and a couple of career development panels. In addition, we worked closely with Manhattan TVC and the MHVTVA to understand the structure of their affiliates and how the Albany TVC can benefit from their experience. We have successfully engaged several key people to work on the above mentioned activities and expect become even stronger in 2022.",
    affActivitiesC: "Albany TVC participated in organizing the US north east Americas annual event, and even had participants for several panels and one-on-one discussions.",
    affActivitiesX: "We organized the Albany Nanotechnology Symposium. http://albanynanotechnology.org/ and the EDS Fall school both of which benefit graduate students and early career professionals. The symposium had over 120 participants -it was a day long event,  whereas the school had around 30 participants and this was a 2-day event.",
    affDiverse: "We organized the PowerUp conference which was an event that spanned over two afternoons. We had several topics that revolved around the common theme 'your impactful voice'. Our panels included: Speaking up & Confidence and Diversity & Inclusion. And we had workshops that included: Career Development & Imposter Syndrome ",
