    affLastValdte: "Tuesday - Dec 01, 2020 17:44",
    affDueValdte: "12/01/2021",
    affActivities: "The “Canadian Technology Transformation Series” initiative presented 17 talks in 2021 by thought leaders within IBM on a variety of topics of importance to IBMers today. The presenters included many IBM Fellows, DEs, STSMs and executives. In total, counting live and views of the recordings, more than 1,400 people attended these talks. The NPS scores from attendees was above 50 for both the live attendees and from those who watched the recordings later, indicating their satisfaction with the talks and the value they delivered. Every presentation was recorded and remains available as a playback in Your Learning and a playlist of all the recordings is also available from Watson Media.",
    affActivitiesC: "CATA was a significant contributor to the three-day Americas Northeast AoT Affiliates & Friends Annual Event this year.  CATA members acted as organizers, presenters, panelists, and moderators for the event and the event was also regularly promoted in the CATA Slack channel.",
    affActivitiesX: "Many CATA members participated in the CASCON x EVOKE 2021 conference which is a conference sponsored in part by IBM, but which has participants from academia and industry all across Canada. CATA also participated in the organization of the conference workshop, \"The 12th CASCON Workshop on Cloud Computing\" along with York University.",
    affDiverse: "Many CATA member participated in the Academy Open Jam and the related “The Open Organization – The Affiliates Experiments” initiative to represent the work done by CATA related to the theme of Diversity, Equity, and Inclusion.",
