    affDueValdte: "11/29/2021",
    affActivities: [
    "1) Co-organized the CEE RTE 2020 (joint initiative):  ",
    "CEE RTE brought 1500 IBMers and more than60 speakers from mainline and CIC together to upskill them, give them strategy for 2021 on Cloud, AI and Garage and helped with connecting the SMEs into unified communities. The outcome connected entire technical community in Mainline and Client Innovation Centers. Plus, there were many successful projects presented that will be reused for pipeline generation. ",
    "2) Co-organized and sponsored the Slovak Space Tech Day 2 & Slovak Aviation Industry Day. ",
    "The event gave visibility and business engagements  with  startups  and  Space  firms  in  the  region,  with  a  focus  on  emerging  technologies  for  space.  The  initiative strengthened IBM relationship with Space companies and empowered IBM footprint in Space Tech in the region.",
    "3) 2020 European Researchers Night: ",
    "The TEC team helped the organizers to highlight IBM's presence in academia in order to offer ways on how we collaborate with researchers and institutions in the region, as well as familiarize the general public with science and research.•Promoting the DE career path for women in technical positions. The initiative raised awareness on how to become a DE for our 4800 participants, by supporting diversity and career paths.",
    "4) Assessing & listing talent and tech-related activities in CEE: ",
    "The initiative unified the efforts of leading TECs in CEE by fostering participation and engagement in a progressively growing and enthusiastic technical CEE community.",
    "5) AoT and Patenting at IBM: ",
    "Together with virtual patent cafés, the focus has been to promote the innovation and patenting in the CEE  region,  which  increased  Intellectual  Property  contributions.  During  2020,  20+  patents  have  been  submitted  by TEC  CZ|SK members, and out of those ~60% have been already filed with the USPTO (others are currently waiting for their evaluation with respective IDTs). In the process, 8 new inventors have been formed, and new members introduced to our TEC, ensuring a bright future for the community and a new set of activities in the years to come.",
    "6) Some of our TEC members are proud DEG Advocates with Silver and Gold status, promoting IBM Cloud and technologies in the region.",
    "7) Our members led and took active roles in global initiatives, such as: Development of Automotive, Aerospace & Defense Supply Chain  Transparency  Reference  Architecture;Future  of  Space  Tech:  thought  leadership  from  IBM  and  Industry;Aerospace  & Defense:IBM capabilities and solutions; Adding additional CEE languages to Watson Discovery -Cloud and CloudPak for Data.",
    "8) The solid preparation of TEC and engaged community has favored the increase of newly recognized AoT members in Slovakia and Czech Republic."
    ],
