    "* IBM Systems role in 4th Platform: Objective is to make other BUs in IBM of the important role that Systems offerings play in the 4th Platform adoption, encompassing legacy and new Cloud native and allowing more with less. - https://aotweb.dal1a.cirrus.ibm.com/initiatives/5fb6485a5e2773001e7e3ffe",
    "* Architectural Flavours - program plan: Increase awareness on architect roles and assignments over various markets. The initiative will design a program for delivering technical enablement sessions, showcasing various architect roles at project level in various markets.Related with Distribute AoT Initiative. Affiliates : TEC Poland, TEC Romania, TEC SPGI. - https://aotweb.dal1a.cirrus.ibm.com/initiatives/5f8015b70da20c00170c83fc"
