    affLastValdte: "Friday - Mar 31, 2017 03:06",
    affDueValdte: "03/31/2018",
    affActivities: [
    "James Darwin (Lead) and Jane Chen (Co-Lead) took over TEC A/NZ after a short hiatus in leadership for about 1 year because the previous chair left IBM in 2019.",
    "We started planning for a Regional Technical Exchange in virtual mode (given the travel restrictions across Australia and New Zealand). The RTE was last held in 2015.",
    "Under the leadership of James and Jane, This year the RTE was held at the end of October 2020, with great success. ",
    "a) Opening by IBM A/NZ GM Katrina Troughton, expressing her confidence in the technical community and the importance of its vitality to IBM.",
    "b) Great opening speech by Peter Brennan, a high ranking official in Services Australia, an important branch of the Federal Government, and IBM A/NZ largest client.",
    "c) We debated the corporate responsibility of making compute green in our data centers with clients and the VP Edan Dionne as well as IBM Researchers.",
    "d) We promoted the professions and the certification in the professions.",
    "e) We promoted the Technical Academy.",
    "f) Gave a voice to the great technical work that is going on in the IBM community in A/NZ",
    "h) Trialed a virtual approach with minimal disruption in the daily activity of participants, with a carefully designed agenda spanning an entire week (2.5hours per day maximum).",
    "i) We focused on celebrating extraordinary contributions from the A/NZ tech community, a focus that will be continued with additional support through HR in IBM A/NZ from 2021 on.",
    "Finally, the event received great feedback.",
    "Newly agreed TEC A/NZ objectives for 2020:",
    "a) focusing on the vitality of our technical community",
    "b) providing them with a platform to be visible",
    "c) promoting excellence",
    "d) promoting professionalism in a formal manner through accreditation efforts",
    "e) providing better networking inside the technical community inside IBM A/NZ and more broadly through the academy, and IBM in general."
    ],
