    affLastValdte: "Friday - Dec 17, 2021 05:21",
    affDueValdte: "12/17/2022",
    affActivities: [
    "•	On the January 1st, 2021, Kenji Kuba, DE, GBS, was appointed to the new TEC-J President. Sachiko Yoshihama, STSM, IBM Research, was appointed to the TEC-J Vice President, along with 8 new TEC-J Steering Committee members to drive technical leadership.",
    "•	Under Kenji Kuba’s leadership, the new slogan of TEC-J was defined as “Shu-Ha-Ri”, meaning “protect-disrupt-leave” in Japanese. He also emphasizes importance of response to various changes, such as the change of the world (e.g., new normal, DX acceleration), change of technologies (e.g., XR, Quantum Computing), and change of IBM (e.g., Kyndryl separation).",
    "•	The number of TEC-J members has reached 765 as of April 2021. ",
    "•	The number of working groups was increased to 70 from 55 last year. The focus of working groups spans across various domains such as AI, Architecture & Solution, Cloud & IOT, Software Engineering, System Infrastructure, Professional Activities, and Socio-Technical Problems.",
    "•	Two members of IBM Japan technical community were appointed to new AoT members in November. One of them, Chie Takeda, is a member of TEC-J Steering Committee.",
    "•	Multiple TEC-J Showcase Events were held throughout the year to share accomplishments of various local initiatives among TEC-J members.",
    "•	Three TEC-J WGs studied AoT initiatives and its adoption in the localized context, and published results through presentations and internal publications.",
    "•	TEC-J Spring Forum was held as an online event and attended by 487 participants from various divisions in IBM Japan. The program consists of various topics including guest a speech by CTO of Microsoft Japan, a panel discussion between CTO of Microsoft and IBM Japan, as well as VR poster sessions where 35 WGs presented their activities in virtual theaters.",
    "•	TEC-J Annual Event was held in November to celebrate the start of the new form of collaboration between IBM and Kyndryl. CEO and CTO of both IBM and Kyndryl gave speeches and shared their thoughts and expectations to the technical employees of both companies. In the panel discussion, technical leaders of both companies had very lively discussions about the future of the new form of collaboration. ",
    "•	Triband TEC Fest for APAC was held in November - December as a multi-week event in collaboration with AoT Affiliates in the APAC region. I attended as a panelist and had very exciting discussion with technical leaders in APAC region. Selected members of TEC-J gave presentations to share knowledge and experience on various topics.",
    "•	A cross-affiliate technical exchange between TEC-Korea and TEC-Japan was held on December 17 to foster collaboration between two communities.",
    "•	TEC-J Open Source Day 2021 was held to advocate open source activities and to share insights from past experiences.",
    "•	Outcome of TEC-J activities are published in various forms, including 8 articles at external on-line magazines called iMagazine, 5 THINK Blog articles, and many more reports and resources internally published on Lighthouse, TechZone and GitHub Enterprise."
    ],
    affActivitiesC: [
    "•	Triband TEC Fest for APAC was held in November - December as a multi-week event in collaboration with AoT Affiliates in the APAC region. Selected members of TEC-J gave presentations to share knowledge and experience on various topics, including COVID-19 Genome Analysis Portal, dynamic web-application automation, and sharing experience of VR poster sessions.",
    "•	A cross-affiliate technical exchange between TEC-Korea and TEC-Japan was held on December 17 to exchange information and foster collaboration between two communities by building networks."
    ],
    affActivitiesX: [
    "•	TEC-J P-TECH Working Group contributed to develop the curriculum which is to be deployed in Japan. They also deployed this to Machida Technical High-school in last year and keep provide the curriculum this year. They had started this for Nihon Kogakuin for this year and contributed to keep success of the P-TECH case in Japan.  (Contact:  Kaori Namba/Japan/IBM)",
    "•	Outcome of TEC-J activities are published in various forms, including 8 articles at external on-line magazines called iMagazine, 5 THINK Blog articles, and many more reports and resources internally published on Lighthouse, TechZone and GitHub Enterprise."
    ],
    affDiverse: [
    "•	TEC-Japan collaborated COSMOS, which is the technical women community in Japan. TEC-Japan members gave presentations at COSMOS Day, an annual event for all the technical women. (Contact: Rika Hiraiwa/Japan/IBM, Kaori Ohsumi/Japan/IBM)",
    "•	TEC-Japan members support the Access Blue program in Japan as a lecturer. (Access Blue Program : Long-term internship for students with disabilities) (Contact: Sachiko Yoshihama/Japan/IBM)"
    ],
